from hypothesis import strategies as st

@st.composite
def gen(draw):
    n = draw(st.integers(1, 8))
    p = []
    for i in range(1, n + 1):
        mode = draw(st.integers(0, 3))
        if mode == 0:
            p.append(1)
        elif mode == 1:
            p.append(i)
        else:
            p.append(draw(st.integers(1, i)))
    return f"{n}\n{' '.join(map(str, p))}\n"

def validate(inp):
    t = inp.split()
    if not t:
        return False
    try:
        n = int(t[0])
        p = [int(x) for x in t[1:]]
    except ValueError:
        return False
    if not (1 <= n <= 5 * 10**5):
        return False
    if len(p) != n:
        return False
    return all(1 <= p[i] <= i + 1 for i in range(n))

def ref(inp):
    t = inp.split()
    n = int(t[0])
    p = [int(x) for x in t[1:1 + n]]
    A = []
    for i in range(1, n + 1):
        # Insert i so that it becomes the P_i-th element (1-indexed).
        A = A[:p[i - 1] - 1] + [i] + A[p[i - 1] - 1:]
    return " ".join(map(str, A))
